WITH enriched AS (SELECT id, units, AVG(revenue) OVER (PARTITION BY store_id ORDER BY sale_date ASC, id ASC ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS revenue_avg_6_prior, LAG(revenue, 2) OVER (PARTITION BY product_id ORDER BY revenue ASC, id ASC) AS prev_revenue, CORR(revenue, units) OVER (PARTITION BY product_id, store_id) AS corr_revenue_units FROM store_sales WHERE sale_date > '2025-08-01'), filtered AS (SELECT id, units, revenue_avg_6_prior, prev_revenue, corr_revenue_units, CAST(units AS DOUBLE) AS units_num FROM enriched WHERE revenue_avg_6_prior < 1807), enriched_store_sales AS (SELECT id, units, revenue_avg_6_prior, units_num, AVG(units_num) OVER w_running AS units_num_avg_6_prior, AVG(prev_revenue) OVER (ORDER BY units ASC, id ASC ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS prev_revenue_avg_2_prior, ROW_NUMBER() OVER w_recent AS seq_no, SUM(revenue_avg_6_prior) OVER w_running_2 AS running_revenue_avg_6_prior FROM filtered WINDOW w_running AS (ORDER BY units ASC, id ASC ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING), w_recent AS (ORDER BY corr_revenue_units ASC, id ASC), w_running_2 AS (ORDER BY units_num ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), base AS (SELECT id, units, units_num, prev_revenue_avg_2_prior, seq_no, running_revenue_avg_6_prior, LEAST(prev_revenue_avg_2_prior, units) AS least_prev_revenue_avg_2_prior_units FROM enriched_store_sales WHERE units_num < 49), scored AS (SELECT *, LAG(units, 1) OVER (ORDER BY units ASC, id ASC) AS prev_units, NTILE(5) OVER (ORDER BY units DESC, id ASC) AS units_bucket FROM base), base_store_sales AS (SELECT id, units, units_num, prev_revenue_avg_2_prior, running_revenue_avg_6_prior, least_prev_revenue_avg_2_prior_units, prev_units, ROUND(units_bucket / running_revenue_avg_6_prior, 2) AS units_bucket_per_running_revenue_avg_6_prior FROM scored WHERE units_bucket = 7) SELECT id, units, prev_revenue_avg_2_prior, running_revenue_avg_6_prior, least_prev_revenue_avg_2_prior_units, units_bucket_per_running_revenue_avg_6_prior FROM base_store_sales ORDER BY id ASC;
